function relayCommand(command, source) { return { topic: 'iot55/device01/cmd/relay', payload: JSON.stringify({ command, source, timestamp_ms: Date.now() }) }; }
function event(type, description, severity = 'ERROR') { return { topic: 'iot55/device01/event', payload: { device_id: 'device01', timestamp_ms: Date.now(), event_type: type, severity, description } }; }

